#include <iostream>
#include <string>
#include <string_view>

std::string_view rootTicker(std::string_view symbol) {
    // view into the original buffer - no copy made
    return symbol.substr(0, symbol.find('-'));
}

int main() {
    std::string sym = "MSFT-0621-C190";
    std::cout << rootTicker(sym) << '\n';     // MSFT
    std::cout << rootTicker("SPY") << '\n';   // SPY (no dash: npos -> whole view)
    return 0;
}

guidedExercise.solution:
Sum $= 406.5$, so the mean is $406.5 / 4 =$ **101.625** (printed as `101.625`). The parameter is `const double*` because the array **decays** to a pointer to its first element - no length survives the call, so the count must be passed explicitly.
```cpp
#include <iostream>

double meanFills(const double* values, std::size_t n) {
    double sum = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        sum += values[i];
    }
    return sum / n;
}

int main() {
    double fills[4] = {101.5, 102.25, 99.75, 103.0};
    std::cout << meanFills(fills, 4) << '\n';   // 101.625
    return 0;
}
```

independentExercise.solution:
dashCount: **2** for "MSFT-0621-C190", **0** for "SPY". optionRoot: **"MSFT"** and **"SPY"**.
```cpp
#include <iostream>
#include <string_view>

std::size_t dashCount(std::string_view s) {
    std::size_t count = 0;
    for (std::size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '-') ++count;
    }
    return count;
}

std::string_view optionRoot(std::string_view s) {
    return s.substr(0, s.find('-'));
}

int main() {
    std::cout << dashCount("MSFT-0621-C190") << '\n';    // 2
    std::cout << dashCount("SPY") << '\n';               // 0
    std::cout << optionRoot("MSFT-0621-C190") << '\n';   // MSFT
    std::cout << optionRoot("SPY") << '\n';              // SPY
    return 0;
}
```
The views returned by optionRoot point into the string literals, which live for the whole program - so nothing dangles here.

